.mgl-dev-settings-toggle{
  position:fixed;right:18px;top:50%;z-index:10040;width:48px;height:48px;display:grid;place-items:center;padding:0;
  border:1px solid rgba(255,255,255,.18);border-radius:15px 0 0 15px;background:#0d3138;color:#f5fbfa;
  box-shadow:0 14px 34px rgba(3,29,35,.22);transform:translateY(-50%);cursor:pointer;
  transition:transform .2s ease,background-color .2s ease,box-shadow .2s ease;
}
.mgl-dev-settings-toggle:hover{background:#0f4247;transform:translateY(-50%) translateX(-3px);box-shadow:0 18px 40px rgba(3,29,35,.28)}
.mgl-dev-settings-toggle:focus-visible{outline:3px solid #00d094;outline-offset:3px}
.mgl-dev-settings-toggle svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;transition:transform .3s ease}
.mgl-dev-settings-toggle:hover svg{transform:rotate(35deg)}
html.mgl-settings-open .mgl-dev-settings-toggle{opacity:0;pointer-events:none}

.mgl-dev-settings-panel{
  position:fixed;top:0;right:0;z-index:10050;width:min(430px,calc(100vw - 20px));height:100dvh;display:flex;flex-direction:column;
  overflow:hidden;border-left:1px solid rgba(255,255,255,.10);background:#0f292f;color:#eef8f6;
  box-shadow:-26px 0 70px rgba(2,24,30,.30);transform:translateX(104%);transition:transform .28s cubic-bezier(.2,.8,.2,1);
}
html.mgl-settings-open .mgl-dev-settings-panel{transform:translateX(0)}
.mgl-dev-settings-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:20px 20px 16px;border-bottom:1px solid rgba(255,255,255,.10)}
.mgl-dev-settings-title{margin:0;color:#fff;font-size:20px!important;font-weight:700!important;line-height:1.2!important;letter-spacing:-.025em!important}
.mgl-dev-settings-kicker{display:block;margin-bottom:4px;color:#6de6c8;font-size:11px!important;font-weight:800!important;line-height:1.3!important;letter-spacing:.12em!important;text-transform:uppercase}
.mgl-dev-settings-close{width:38px;height:38px;display:grid;place-items:center;padding:0;border:1px solid rgba(255,255,255,.12);border-radius:11px;background:rgba(255,255,255,.05);color:#fff;cursor:pointer}
.mgl-dev-settings-close:hover{background:rgba(255,255,255,.10)}
.mgl-dev-settings-close:focus-visible{outline:3px solid #00d094;outline-offset:2px}
.mgl-dev-settings-body{flex:1;overflow:auto;padding:18px}
.mgl-dev-settings-section{padding:16px;border:1px solid rgba(255,255,255,.10);border-radius:16px;background:rgba(255,255,255,.045)}
.mgl-dev-settings-section+.mgl-dev-settings-section{margin-top:12px}
.mgl-dev-settings-section-title{margin:0 0 12px!important;color:#fff!important;font-size:15px!important;font-weight:800!important;line-height:1.3!important;letter-spacing:0!important}
.mgl-dev-settings-label{display:block;margin-bottom:7px;color:#dff3ef;font-size:12px!important;font-weight:700!important;line-height:1.35!important}
.mgl-dev-settings-search,.mgl-dev-settings-select,.mgl-dev-control input,.mgl-dev-control select{
  width:100%;min-height:42px;padding:9px 11px;border:1px solid rgba(255,255,255,.16);border-radius:10px;background:#14373e;color:#fff;
  font-size:13px!important;font-weight:600!important;line-height:1.4!important;outline:none;
}
.mgl-dev-settings-search{margin-bottom:8px}
.mgl-dev-settings-search:focus,.mgl-dev-settings-select:focus,.mgl-dev-control input:focus,.mgl-dev-control select:focus{border-color:#00d094;box-shadow:0 0 0 3px rgba(0,208,148,.14)}
.mgl-dev-settings-meta{display:flex;align-items:center;gap:8px;margin-top:8px;color:#9eb8b4;font-size:11px!important;line-height:1.45!important}
