.mgl-dev-settings-dot{width:7px;height:7px;flex:0 0 7px;border-radius:50%;background:#00d094;box-shadow:0 0 0 4px rgba(0,208,148,.10)}
.mgl-dev-settings-grid,.mgl-dev-heading-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.mgl-dev-heading-grid{margin-top:10px;grid-template-columns:repeat(3,1fr)}
