.mgl-dev-settings-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}
.mgl-dev-settings-button{min-height:42px;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:9px 11px;border:1px solid rgba(255,255,255,.13);border-radius:11px;background:rgba(255,255,255,.07);color:#fff;font-size:13px!important;font-weight:800!important;line-height:1.2!important;text-decoration:none!important;cursor:pointer}
