.tm-color-switcher {

	position: fixed;
	left: 8px;
	top: 50%;
	z-index: 1000;
	display: block;

	-webkit-transform: translateY(-50%);
	-ms-transform: translateY(-50%);
	transform: translateY(-50%); 	

	text-align: center;

	border-radius: 64px;
	
	box-shadow: 0 0 25px rgba(0,0,0,.08);

	padding: 15px 10px 15px 10px;
	background-color: #fff;
    font-size: 12px;
    width: 65px;
    line-height: 1.3;
}

.tm-color-switcher img {
}


.tm-color-switcher .close {

	font-size: 14px;
	border-radius: 50%;
	position: absolute;
	top: 0;
	right: 0;

	font-size: 20px;
	color: #CE4F4D;
	z-index: 20;
	text-align: center;
	line-height: 20px;
	width: 20px;
	height: 20px;
	display: block;
	opacity: 1;
	background-color: #EEEEEE;
	transition: all 0.5s ease;
	cursor: pointer;
}

.tm-color-switcher.closed {

	padding: 10px 8px 6px 10px;
	left: 0;
	border-top-left-radius: 0;
	border-bottom-left-radius: 0;
	transition: all 0.25s ease;
}

.tm-color-switcher.closed:hover {

	padding-right: 14px;
}

.tm-font-selector:hover {

	cursor: pointer;
}

.tm-color-switcher.closed img:hover {

	cursor: pointer;
}

.tm-color-switcher.closed .close {

	display: none;
}

.tm-color-switcher.closed div {

	display: none;
}

.tm-color-switcher.closed .img {

	display: block;
	overflow: hidden;
	height: 34px;
	width: 36px;
	text-align: center;
}

.tm-color-switcher.closed .img img {

	margin: 0;
}

.tm-color-switcher .close:hover {

	opacity: 1;
